class ReifiedTripleRefEvaluationContractTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PROPOSITION_FORM = VF.createIRI("urn:proposition-form");
	private static final IRI SUBJECT = VF.createIRI("urn:subject");
	private static final IRI PREDICATE = VF.createIRI("urn:predicate");
	private static final IRI OBJECT = VF.createIRI("urn:object");
	private static final IRI ANNOTATION = VF.createIRI("urn:annotation");

	@Test
	void standaloneMetadataMatchesGenericEvaluationBindingDomain() {
		ReifiedTripleRef ref = new ReifiedTripleRef(
				new Var("subject"),
				new Var("predicate"),
				new Var("object"),
				new Var("tripleTerm"),
				new Var("reifier"));
		StrictEvaluationStrategy strategy = strategy(encodedTripleStatements());

		List<BindingSet> results = evaluate(strategy, ref);

		assertThat(results).singleElement().satisfies(result -> {
			assertThat(result.getBindingNames())
					.containsExactlyInAnyOrder("subject", "predicate", "object", "tripleTerm");
			assertThat(ref.getBindingNames()).isEqualTo(result.getBindingNames());
			assertThat(ref.getAssuredBindingNames()).isEqualTo(result.getBindingNames());
		});
	}

	@Test
	void parserGeneratedReifiesPatternOwnsMultiplicity() {
		IRI firstReifier = VF.createIRI("urn:reifier:first");
		IRI secondReifier = VF.createIRI("urn:reifier:second");
		List<Statement> statements = List.of(
				VF.createStatement(PROPOSITION_FORM, RDF.TYPE, RDF.PROPOSITION_FORM),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_SUBJECT, SUBJECT),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_PREDICATE, PREDICATE),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_OBJECT, OBJECT),
				VF.createStatement(firstReifier, RDF.REIFIES, PROPOSITION_FORM),
				VF.createStatement(secondReifier, RDF.REIFIES, PROPOSITION_FORM),
				VF.createStatement(firstReifier, ANNOTATION, VF.createLiteral("first")),
				VF.createStatement(secondReifier, ANNOTATION, VF.createLiteral("second")));
		ParsedQuery query = QueryParserUtil.parseQuery(QueryLanguage.SPARQL,
				"SELECT ?subject ?value WHERE { "
						+ "<< ?subject <urn:predicate> <urn:object> >> <urn:annotation> ?value }",
				null);

		List<BindingSet> results = evaluate(strategy(statements), query.getTupleExpr());

		assertThat(results).hasSize(2);
		assertThat(results).extracting(result -> result.getValue("subject"))
				.containsOnly(SUBJECT);
		assertThat(results).extracting(result -> result.getValue("value"))
				.containsExactlyInAnyOrder(VF.createLiteral("first"), VF.createLiteral("second"));
	}

	private static List<Statement> encodedTripleStatements() {
		return List.of(
				VF.createStatement(PROPOSITION_FORM, RDF.TYPE, RDF.PROPOSITION_FORM),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_SUBJECT, SUBJECT),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_PREDICATE, PREDICATE),
				VF.createStatement(PROPOSITION_FORM, RDF.PROPOSITION_FORM_OBJECT, OBJECT));
	}

	private static StrictEvaluationStrategy strategy(List<Statement> statements) {
		return new StrictEvaluationStrategy(new ListTripleSource(statements), null);
	}

	private static List<BindingSet> evaluate(StrictEvaluationStrategy strategy, TupleExpr expression) {
		try (CloseableIteration<BindingSet> results = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			return results.stream().toList();
		}
	}

	private static final class ListTripleSource implements TripleSource {

		private final List<Statement> statements;

		private ListTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.filter(statement -> contexts.length == 0 || Arrays.stream(contexts)
							.anyMatch(context -> Objects.equals(context, statement.getContext())))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
}
